# group_consecutive :: [1, 1, 2, 2, 3, 1]
from itertools import groupby

def group_consecutive(xs):
    return [list(g) for _, g in groupby(xs)]

if __name__ == '__main__':
    print(group_consecutive([1, 1, 2, 2, 3, 1]))

